terms={'sqrt t':t**0.5,'P':P,'P^2':P**2,'P^3':P**3,'t':t,'P t':P*t,'P^2 sqrt t':P**2*t**0.5,'P sqrt t':P*t**0.5,'P^2 t':P**2*t,'P^3 sqrt t':P**3*t**0.5,'P^2 t^1.5':P**2*t**1.5,'1':np.ones_like(t),'P^3 t':P**3*t,'P^2/t':P**2/t,'sqrt t *P^3':P**3*t**0.5,'P^1.5':P**1.5,'P^2 t^2':P**2*t**2}
names=list(terms)
def test(sel):
    A=np.column_stack([terms[n] for n in sel])
    c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    res=y-A@c
    return np.mean(res**2)/np.var(y), c
